// SPDX-License-Identifier: MIT
pragma solidity =0.8.0;    

interface IValidations {

    enum ValidationStatus {Undefined, Yes, No}   


       struct Validation {
        bool cohort;
        address requestor;
        uint256 validationTime;
        uint256 executionTime;
        string url;
        uint256 consensus;
        uint256 validationsCompleted;
        uint64 winnerConfirmations;
        address winner;
        uint256 price;
        uint64 registeredNum;
    }   


    function outstandingValidations(address enterprise) external view returns (uint256);
    function returnValidationUrl(bytes32 valHash, address user) external  view returns(string memory url);
    function returnWinnerPoints(bytes32 valHash, address user) external  view returns(uint256 plus, uint256 minus);
    function selectWinner(bytes32 valHash, address[] memory winners) external view returns (address);
    function returnValidatorList(bytes32 valHash) external view  returns (address[] memory);
    // function returnValidatorList() external view returns (address[] memory);
    // function validatorTime(address validator) external view returns (uint256);
    // function validatorChoice(address validator) external view returns(uint8);
    // function validationUrl(address validator) external view returns(string memory);
    // function validationHash(address validator) external view returns(bytes32);
    // function validation(bytes32 valHash) external view returns (Validation memory);





     function collectValidationResults(bytes32 valHash)
        external
        view
        returns (
            address[] memory,
            uint256[] memory,
            uint256[] memory,
            uint256[] memory,
            string[] memory,
            bytes32[] memory
        );

    function returnValidationRecord(bytes32 valHash) external  view
        returns( bool cohort,
                address requestor,
                uint256 validationTime,
                uint256 executionTime,
                string memory url,
                uint256 consensus,
                uint256 validationsCompleted,
                uint64 winnerConfirmations,
                bool paymentSent,
                address winner);

}
